pub fn derive_repository_snapshot_id(
    repository_id: u64,
    graph_snapshot_id: u64,
    catalogue_checksum: u64,
    unresolved_checksum: u64,
    facts_checksum: u64,
    adapter_name: &str,
    adapter_version: &str,
) -> u64 {
    let mut hasher = StableHasher::new();
    hasher.update(b"arcana-repository-snapshot-v1");
    for value in [
        repository_id,
        graph_snapshot_id,
        catalogue_checksum,
        unresolved_checksum,
        facts_checksum,
    ] {
        hasher.update(&value.to_le_bytes());
    }
    hasher.update(adapter_name.as_bytes());
    hasher.update(&[0]);
    hasher.update(adapter_version.as_bytes());
    hasher.finish()
}

fn unique_repository_identity(facts: &RepositoryFacts) -> Option<u64> {
    let mut repositories = facts
        .nodes
        .iter()
        .filter(|node| node.kind == NodeKind::Repository);
    let first = repositories.next();
    if let Some(repository) = first
        && repositories.next().is_none()
    {
        Some(repository.key.0)
    } else {
        None
    }
}

